/* Editorial interactions, independent from the original hero. */
const world=document.querySelector('.mv-world');
if(!reduced.matches&&'IntersectionObserver' in window){
 world.classList.add('mv-motion');
 const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('mv-visible');observer.unobserve(entry.target);}}),{threshold:.08});
 world.querySelectorAll('.mv-reveal').forEach(el=>observer.observe(el));
 reduced.addEventListener('change',e=>{if(e.matches)world.classList.remove('mv-motion');});
}
function addSelection(items){bag.push(...items);const count=document.querySelector('.bag-count');count.hidden=false;count.textContent=bag.length;document.querySelector('.announcement').textContent=`${items.length===1?'Un beso añadido':items.length+' besos añadidos'} a tu selección`;showBag();}
document.querySelectorAll('[data-add]').forEach(button=>button.addEventListener('click',()=>addSelection([button.dataset.add])));
document.querySelector('#add-box').addEventListener('click',()=>{const choice=document.querySelector('[name=box]:checked').value;addSelection(choice==='surtida'?['matcha','matcha','cacao','cacao','vainilla','vainilla']:Array(6).fill(choice));});
const noteContent={matcha:{title:'Un verde con carácter.',text:'El matcha pone la nota vegetal. La cobertura suave y las pequeñas virutas de chocolate blanco encuentran el equilibrio. El hojaldre hace el resto.',pair:'Un té suave, una charla larga.'},cacao:{title:'Intensidad, capa a capa.',text:'El chocolate negro aporta profundidad. Las virutas suman textura y el hojaldre tostado le da un contrapunto delicado. Un sabor para quedarse un rato.',pair:'Un café corto, una sobremesa sin reloj.'},vainilla:{title:'La belleza de lo sencillo.',text:'Vainilla aromática, glaseado suave y un toque de azúcar sobre el dorado del hojaldre. Una combinación cálida, familiar y llena de pequeños matices.',pair:'Una infusión floral, tu momento favorito.'}};
const noteTabs=[...document.querySelectorAll('[data-note]')];
function selectNote(button){const flavor=button.dataset.note,content=noteContent[flavor];noteTabs.forEach(tab=>{tab.setAttribute('aria-selected',String(tab===button));tab.tabIndex=tab===button?0:-1;});const panel=document.querySelector('#flavor-panel');panel.setAttribute('aria-labelledby',button.id);panel.querySelector('h3').textContent=content.title;panel.querySelector(':scope > p').textContent=content.text;panel.querySelector('.mv-pair p').textContent=content.pair;document.querySelector('.mv-notes-word').textContent=flavor;document.querySelector('.mv-notes-cookie').src=`./assets/cookie-${flavor}.webp`;document.querySelector('.mv-notes-deco').src=`./assets/deco-${flavor}.webp`;if(!reduced.matches)[panel,document.querySelector('.mv-notes-cookie')].forEach(el=>el.animate([{opacity:.15,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:420,easing:'ease-out'}));}
noteTabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectNote(tab));tab.addEventListener('keydown',e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const target=e.key==='Home'?0:e.key==='End'?2:(index+(e.key==='ArrowRight'?1:2))%3;noteTabs[target].focus();selectNote(noteTabs[target]);});});
document.querySelector('#privacy-info').addEventListener('click',()=>show('Privacidad','<p>Esta experiencia de presentación no incluye formularios de envío, pagos ni herramientas de analítica añadidas por MIGA VERDE.</p><p>La selección de productos se guarda únicamente en la memoria de esta página y desaparece al recargar. El proveedor de alojamiento puede conservar registros técnicos de acceso.</p>'));
document.querySelector('#mv-year').textContent=new Date().getFullYear();
